import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.TQKaXlFR.js";const k=JSON.parse('{"title":"升级与回退计划","description":"","frontmatter":{},"headers":[],"relativePath":"releases/upgrade.md","filePath":"releases/upgrade.md"}'),l={name:"releases/upgrade.md"};function r(o,e,n,h,p,d){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="升级与回退计划" tabindex="-1">升级与回退计划 <a class="header-anchor" href="#升级与回退计划" aria-label="Permalink to &quot;升级与回退计划&quot;">​</a></h1><p>本页向部署负责人说明从已有候选到新配对版本的操作顺序。前提是明确当前前后端/数据库/文档版本、有恢复点和维护窗口；当前没有“一键无损升级”工具。</p><h2 id="升级前确认" tabindex="-1">升级前确认 <a class="header-anchor" href="#升级前确认" aria-label="Permalink to &quot;升级前确认&quot;">​</a></h2><ol><li>获取真实目标代码提交、变更说明和迁移文件，不依据package版本或页面标题判断。</li><li>从现有数据库只读导出history，核对所有versioned/repeatable记录、checksum、success和location。</li><li>检查默认baseline false、DB_URL统一配置、JWT/主密钥与Redis双客户端覆盖是否符合当前代码。</li><li>确认旧模块退役和菜单整理对自己扩展的表、授权和页面是否有影响。</li><li>按<a href="./../operations/backup-restore.html">备份恢复</a>保存数据库、对象、主密钥、配置和可回退产物。</li></ol><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, script, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">checksum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, success</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flyway_schema_history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> installed_rank;</span></span></code></pre></div><p>如果库无history但非空，不走普通升级；先审查人工baseline/前向迁移方案。不能直接启用自动baseline到2而假设结构与V1/V2相同。</p><h2 id="隔离演练" tabindex="-1">隔离演练 <a class="header-anchor" href="#隔离演练" aria-label="Permalink to &quot;隔离演练&quot;">​</a></h2><p>恢复一个经过授权的数据副本到隔离schema，连接隔离Redis和对象快照，关闭真实邮件/短信/微信/模型供应商动作。以目标JAR启动，验证strict迁移/重启、账号权限、三组菜单、文件历史读取和关键业务资源。</p><p>已有optional R历史必须保留<code>classpath:db/optional-migration</code>；漏location可能导致missing校验，不能改ignore模式掩盖。当前新空库质量验证23条history不等于你的存量库升级结果，不能用空库测试代替这一演练。</p><p>演练成功须记录代码/产物摘要、迁移前后history、业务核对结果和明确未验证项；失败先查实际DDL部分执行，不反复运行repair/clean。MySQL5.7/8.0兼容矩阵未运行时，目标数据库版本的风险仍需自己验证。</p><h2 id="ai工作区升级后的权限与会话刷新" tabindex="-1">AI工作区升级后的权限与会话刷新 <a class="header-anchor" href="#ai工作区升级后的权限与会话刷新" aria-label="Permalink to &quot;AI工作区升级后的权限与会话刷新&quot;">​</a></h2><p>包含 <code>V20261016_227__restore_ai_request_list_action.sql</code> 的版本将 <code>ai:request:list</code> 恢复为独立F动作，仅向原旧日志页已有明确授权、且迁移时有效的角色迁移。配置/场景动作或动态派生的监控导航不会因此获得日志读取权，<code>ai:monitor:enter</code> 也不替代日志列表或审计权限。</p><p>用户信息与路由缓存前缀随该版本升为v227，但已有登录会话仍可能保留旧权限快照。升级后通过正常“退出登录→重新登录”刷新会话；即使 <code>/user/info</code> 已显示新权限，也不能据此认定原会话中的服务端调用身份已刷新。若日志权限或监控调用统计仍不符合预期，重新登录后再核对角色的实际动作授权与接口结果，不通过扩大授权或清空共享Redis解决。</p><p>本说明是升级核对项，不代表该版本已完成整体验收。迁移结果、当前角色权限及新会话行为仍需在目标环境确认。</p><h2 id="对话与多渠道配置升级核对" tabindex="-1">对话与多渠道配置升级核对 <a class="header-anchor" href="#对话与多渠道配置升级核对" aria-label="Permalink to &quot;对话与多渠道配置升级核对&quot;">​</a></h2><p>本轮新增V240、V242、V243、V244与V245，分别涉及完整对话、独立数据库读取动作、Key轮换维护、独立AI配置菜单、Key材料隔离与设置保存幂等；作用和文件名见<a href="./../reference/database-migrations.html#对话、多-key-与独立配置页增量">迁移增量</a>。实际部署以目标分支完整目录及逐条history为准，本节不声明本轮已发布或在目标库验证成功。</p><p>备份原配置密文与CONFIG_MASTER_KEY。升级后正常重新登录，核对AI配置独立入口、配置list/query/add/edit/test/enable分别授权、数据库读取动作及租户拒绝。已有单Key格式兼容；普通多Key页面应提交完整目标Key集合，保留的旧Key空值不更换材料，缺失项视为从目标草稿移除。</p><p>先读取原渠道和对话，核对pendingChanges及原active状态。模型扫描只读目录，不会自动完成连接验证；新增或替换Key需单独测试。对多个独立服务商的切换应在受控故障条件下验证预算与partial不拼接；不要把扫描成功、同一服务商多Key或静态演示当作供应商生成和故障恢复已通过。旧无正文请求保留历史状态，不补造消息。</p><h2 id="正式窗口" tabindex="-1">正式窗口 <a class="header-anchor" href="#正式窗口" aria-label="Permalink to &quot;正式窗口&quot;">​</a></h2><h3 id="sql查询助手配套升级" tabindex="-1">SQL查询助手配套升级 <a class="header-anchor" href="#sql查询助手配套升级" aria-label="Permalink to &quot;SQL查询助手配套升级&quot;">​</a></h3><p>本轮增加V247查询助手、V248业务模型及V249模型目录票据，目标默认目录为37个versioned迁移，历史optional按部署实际另核对。助手仅持久化安全请求与校验结果，原场景增加兼容的sqlBindings快照；旧版本缺失该字段按空列表读取。升级后保留旧中文变量与已存Key限制，不批量改写既有场景。正文保存省略modelPolicy时保留路由；备用顺序和Key限制通过独立AI配置入口维护，共用revision防止覆盖。</p><p>业务模型与旧渠道分别保留；不会自动把所有上游模型建成新的业务身份或替换旧场景。可按实际需要新建稳定调用名称并绑定已有验证渠道，再显式调整场景。存量渠道没有历史目录票据时显示未获取，重新获取后可刷新重读；目录状态不影响既有连接证明，也不代替新Key测试。</p><p>部署需保留现有Connector/J只读传播及Druid Wall。先在隔离数据库执行三套服务门槛，确认MySQL会话只读、实际拒写与归还连接后的恢复，再核对租户和个人数据政策。租户业务需要以代码登记明确归属政策，未知表不能靠给模型添加提示词开放。SQL参数及结果采用精确数值协议，前后端应配套升级，不能将19位主键转为JavaScript Number。</p><ol><li>暂停写入与相关调度，确认新的恢复点。</li><li>部署目标后端、私有配置和稳定主密钥，执行迁移与启动。</li><li>发布配套前端/runtime配置及文档dist，保持同源/api和/docs/。</li><li>以最小自有账号做登录/菜单/本人通知、授权拒绝和关键业务核对。</li><li>查看迁移/服务错误，确认通过后恢复流量和调度。</li></ol><p>不要在运行同一schema迁移时同时启动多个不同版本的后端。私有密钥文件不随dist发布；前端哈希资源发布采用过渡策略，减少旧HTML找不到chunk的问题。</p><h2 id="失败决策" tabindex="-1">失败决策 <a class="header-anchor" href="#失败决策" aria-label="Permalink to &quot;失败决策&quot;">​</a></h2><p>如果目标启动失败，先判断是配置/依赖、迁移前失败还是DDL已经改变schema。只在旧代码与新schema明确兼容时回退代码；否则恢复已验证的成套DB/对象/密钥/配置/产物。恢复窗口的数据取舍应由业务负责人确认。</p><p>修改成功迁移、删history、放宽validate或改变主密钥不能作为回退方法。错误主密钥导致旧密文不可解密时优先恢复原值；当前没有自动重加密工具，不宣称随意换密钥可无损继续。</p><h2 id="正常结果与源码" tabindex="-1">正常结果与源码 <a class="header-anchor" href="#正常结果与源码" aria-label="Permalink to &quot;正常结果与源码&quot;">​</a></h2><p>预期是目标提交对应的迁移全部成功、重启严格校验、原有业务/对象可读、当前权限正确，文档与运行版一致。本文流程未经读者自己的环境演练不自动成为其生产验收证明。</p><p>依据：后端<code>application.yml</code>、<code>db/migration/</code>与<code>db/optional-migration/</code>、<code>SecretCipher</code>及<code>ReleaseServicesIT</code>；前端<code>apps/web-ele/.env.production</code>、<code>src/router/routes-helper.ts</code>、<code>scripts/build-quality.mjs</code>。完整工具命令见<a href="./../operations/quality-gates.html">质量门槛</a>，当前限制见<a href="./versions.html">版本组合</a>。</p>`,31)])])}const u=a(l,[["render",r]]);export{k as __pageData,u as default};
